import React from "react";
import type { ThemePack, ThemeSurfaceName, ThemeVars } from "../theme-packs";
import { resolveThemeSurface } from "../theme-appearance";

/** A miniature window uses the pack's own surfaces in each appearance mode. */
export function ThemePackPreview({ pack }: { pack: ThemePack }) {
  return (
    <span aria-hidden="true" className="block w-full" data-theme-preview={pack.id}>
      <PreviewMode pack={pack} mode="light" className="dark:hidden" />
      <PreviewMode pack={pack} mode="dark" className="hidden dark:block" />
    </span>
  );
}

function PreviewMode({
  pack,
  mode,
  className,
}: {
  pack: ThemePack;
  mode: "light" | "dark";
  className: string;
}) {
  const colors = pack.colors[mode];
  const basePalette: ThemeVars = {
    "--cs-background": mode === "light" ? "240 20% 99%" : "240 9% 5.5%",
    "--cs-muted": mode === "light" ? "240 6% 95.5%" : "240 4% 15%",
    "--cs-card": mode === "light" ? "0 0% 100%" : "240 7% 8.5%",
    ...colors,
  };
  const foreground = colors["--cs-foreground"] ?? (mode === "light" ? "240 6% 18%" : "0 0% 92%");
  const accent = colors["--cs-primary"] ?? pack.swatch;
  const surface = (name: ThemeSurfaceName) => {
    const resolved = resolveThemeSurface(pack, name, mode, basePalette);
    return {
      ...resolved,
      color: `hsl(${resolved.background} / ${resolved.backgroundOpacity})`,
    };
  };
  const windowSurface = surface("window");
  const frame = pack.frame?.[mode] ?? pack.frame?.light ?? colors["--cs-border"] ?? accent;
  const paint = (name: "window" | "sidebar" | "titlebar" | "chat" | "composer") => {
    const layer = surface(name);
    return layer.image ? (
      <img
        src={layer.image}
        alt=""
        className="pointer-events-none absolute inset-0 h-full w-full"
        style={{
          objectFit: layer.fit,
          objectPosition: layer.position,
          opacity: layer.opacity,
        }}
      />
    ) : null;
  };
  return (
    <span className={className}>
      <span
        className="relative block h-28 overflow-hidden rounded-lg border"
        style={{
          backgroundColor: windowSurface.color,
          color: `hsl(${foreground})`,
          borderColor: `hsl(${frame})`,
          borderWidth: pack.frame?.width ? Math.min(pack.frame.width, 3) : 1,
        }}
      >
        {paint("window")}
        <span className="relative flex h-full flex-col">
          <span
            className="relative flex h-5 shrink-0 items-center gap-1 border-b border-current/10 px-2"
            style={{ backgroundColor: surface("titlebar").color }}
          >
            {paint("titlebar")}
            <span className="relative size-1 rounded-full bg-current/30" />
            <span className="relative size-1 rounded-full bg-current/20" />
            <span className="relative size-1 rounded-full bg-current/20" />
          </span>
          <span className="flex min-h-0 flex-1">
            <span
              className="relative flex w-12 shrink-0 flex-col gap-2 overflow-hidden border-r border-current/10 p-2"
              style={{ backgroundColor: surface("sidebar").color }}
            >
              {paint("sidebar")}
              <span
                className="relative h-1 w-6 rounded-full"
                style={{ backgroundColor: `hsl(${accent})` }}
              />
              <span className="relative h-1 w-5 rounded-full bg-current/20" />
              <span className="relative h-1 w-6 rounded-full bg-current/10" />
            </span>
            <span
              className="relative flex min-w-0 flex-1 flex-col justify-between overflow-hidden p-2.5"
              style={{ backgroundColor: surface("chat").color }}
            >
              {paint("chat")}
              <span className="relative block space-y-1.5">
                <span
                  className="ml-auto block h-3 w-10 rounded-md"
                  style={{ backgroundColor: `hsl(${accent} / 0.2)` }}
                />
                <span className="block h-1 w-3/5 rounded-full bg-current/20" />
                <span className="block h-1 w-2/5 rounded-full bg-current/10" />
              </span>
              <span
                className="relative block h-4 overflow-hidden rounded border border-current/15"
                style={{ backgroundColor: surface("composer").color }}
              >
                {paint("composer")}
                <span
                  className="absolute right-1 top-1 size-1.5 rounded-sm"
                  style={{ backgroundColor: `hsl(${accent})` }}
                />
              </span>
            </span>
          </span>
        </span>
      </span>
    </span>
  );
}

import type { CssVarName, ThemePack, ThemeSurfaceName, ThemeVars } from "./theme-packs";

const SURFACE_BACKGROUNDS: Record<ThemeSurfaceName, [CssVarName, number]> = {
  window: ["--cs-background", 1],
  sidebar: ["--cs-muted", 0.25],
  titlebar: ["--cs-background", 0.9],
  chat: ["--cs-background", 0],
  composer: ["--cs-card", 1],
  panel: ["--cs-background", 1],
};

/** Resolve once for both the actual host surface and its settings preview.
 * The host retains CSS tokens; miniature previews supply their own base palette.
 */
export function resolveThemeSurface(
  pack: ThemePack,
  name: ThemeSurfaceName,
  mode: "light" | "dark",
  basePalette: ThemeVars = {},
) {
  const appearance = pack.surfaces?.[name];
  // An explicit slot owns its whole surface, including intentionally no image.
  const source = appearance ?? (name === "window" ? pack.wallpaper : undefined);
  const image = source?.[mode] ?? source?.light;
  const color = appearance?.background?.[mode] ?? appearance?.background?.light;
  const [baseToken, baseOpacity] = SURFACE_BACKGROUNDS[name];
  return {
    image,
    opacity: image ? (source?.opacity ?? 1) : 0,
    fit: appearance?.fit ?? "cover",
    position: (appearance?.position ?? "center").replace("-", " "),
    background: color ?? basePalette[baseToken] ?? `var(${baseToken})`,
    backgroundOpacity: appearance?.backgroundOpacity ?? (color ? 1 : baseOpacity),
  };
}

export type ThemeVars = Partial<Record<CssVarName, string>>;

/**
 * Pet visual states a pack can supply a distinct sprite for. `idle`/`running`/
 * `alert` are the core trio; the rest mirror the Codex atlas's richer moods and
 * are optional — a pack that omits them just never shows those moods.
 */
export type PetSpriteState =
  | "idle"
  | "running"
  | "alert"
  | "waving"
  | "jumping"
  | "waiting"
  | "failed";

/**
 * Per-state pet sprite urls (builtin: bundled asset url; installed: cstheme://),
 * plus optional drag frame sequences. `walk` is the rightward/default run loop
 * cycled while dragging; `walkLeft` is the leftward loop (falls back to `walk`
 * when absent). A pack with no walk frames simply shows its idle sprite mid-drag.
 */
export type PetSprites = Partial<Record<PetSpriteState, string>> & {
  /** Ordered frames cycled during a rightward (or undirected) drag. */
  walk?: string[];
  /** Ordered frames for a leftward drag; falls back to `walk` when absent. */
  walkLeft?: string[];
};

export interface WallpaperSpec {
  light?: string;
  dark?: string;
  /** 0..1 blend over the base color; defaults to 1 when a url is present. */
  opacity?: number;
}

/** Static image surfaces supported by the Desktop host. */
export const THEME_SURFACE_NAMES = [
  "window",
  "sidebar",
  "titlebar",
  "chat",
  "composer",
  "panel",
] as const;

export type ThemeSurfaceName = (typeof THEME_SURFACE_NAMES)[number];

export interface ThemeSurfaceSpec extends WallpaperSpec {
  fit?: "cover" | "contain";
  position?: "center" | "top" | "bottom" | "left" | "right" | "top-right" | "bottom-right";
  /** Unitless HSL triples, independent of the image's opacity. */
  background?: { light?: string; dark?: string };
  backgroundOpacity?: number;
}

export interface ThemeFrameSpec {
  light?: string;
  dark?: string;
  /** Inset decorative border in CSS pixels; never changes the layout. */
  width?: number;
  radius?: number;
}

export interface ThemePack {
  /** Stable id persisted to localStorage. */
  id: string;
  /** i18n key (builtin) or plain display name (installed). */
  name: TranslationKey | string;
  /** Representative color (unitless HSL) for the picker swatch — the pack's primary. */
  swatch: string;
  colors: {
    light: ThemeVars;
    dark: ThemeVars;
  };
  /** Optional per-state pet sprites; missing states fall back to the default dog. */
  pet?: PetSprites;
  /** Optional background image; absent means the plain color background. */
  wallpaper?: WallpaperSpec;
  /** Per-area decoration; the legacy wallpaper is the window fallback. */
  surfaces?: Partial<Record<ThemeSurfaceName, ThemeSurfaceSpec>>;
  /** Decorative outer frame for the main app window only. */
  frame?: ThemeFrameSpec;
  /** Optional short UI cues, played only after the user enables theme sounds. */
  sounds?: ThemeSounds;
  /** Local audio assets or explicit external listening links. Never auto-played. */
  music?: ThemeMusicTrack[];
  /** builtin ships with the app; installed comes from ~/.code-shell/themes/. */
  source?: "builtin" | "installed";
}

/**
 * Signals from the pet widget's activity that map to a sprite state, in priority
 * order: a transient `greeting` gesture (idle "hi, I'm here") wins briefly,
 * then active work, then a ready/completed alert, else idle. Pure so it can be
 * unit-tested and reused across windows.
 */
export function petVisualState(activity: {
  runningCount?: number;
  alertCount?: number;
  /** A short-lived "just went idle" cue → a waving gesture. */
  greeting?: boolean;
}): PetSpriteState {
  if (activity.greeting && (activity.runningCount ?? 0) === 0 && (activity.alertCount ?? 0) === 0) {
    return "waving";
  }
  if ((activity.runningCount ?? 0) > 0) return "running";
  if ((activity.alertCount ?? 0) > 0) return "alert";
  return "idle";
}

export const DEFAULT_PACK_ID = "default";

/**
 * Built-in packs. `default` overrides nothing (falls through to the base sheet,
 * i.e. the current brand orange). Accent packs recolor the primary + focus ring
 * (and its foreground for contrast) in both modes; everything else inherits the
 * neutral base so density/contrast tuning is preserved. Character themes also
 * provide their full palette, bundled surface artwork and window frame.
 */
